  forAll { (fa: IO[Int]) => Concurrent[IO].memoize(fa).flatten eqv fa }
}

class GenSpawnSpec extends Specification { outer =>

  type F[A] = PureConc[Unit, A]
  val F = Spawn[F]

  "spawn" should {
    "raceOutcome" should {
      "not hang" in {
        Eq[F[Unit]].eqv(F.raceOutcome(F.never, F.canceled).void, F.unit)
      }

def endState(ec: ExitCase[Throwable]) =
  state.modify {
    case None =>
      throw new AssertionError("unreachable")
    case s @ Some(Fetch(Done, _, _)) =>
      s -> F.unit
    case Some(Fetch(Subs(n), v, stop)) =>
      if (ec == ExitCase.Canceled && n == 1)
        None -> stop.get.flatten
      else if (ec == ExitCase.Canceled)
        Fetch(Subs(n - 1), v, stop).some -> F.unit
      else
        Fetch(Done, v, stop).some -> F.unit
  }.flatten

def fetch =
  f.attempt
    .flatMap(v.complete)
    .start
    .flatMap(fiber => stop.complete(fiber.cancel))

@tailrec def loop[C](current: Resource[G, C], stack: Stack[C]): G[B] =
  current.invariant match {
    case Allocate(resource) =>
      F.bracketCase(resource) {
        case (a, _) =>
          stack match {
            case Nil               => onOutput(a)
            case Frame(head, tail) => continue(head(a), tail)
          }
      } {
        case ((_, release), ec) =>
          onRelease(release(ec))
      }
    case Bind(source, fs) =>
      loop(source, Frame(fs, stack))
    case Suspend(resource) =>
      F.flatMap(resource)(continue(_, stack))
  }
